  List<List<int>> segmentations = [];

  for (int i = 0; i <= s.length - word.length; i++) {
    if (dp[i] && wordDict.contains(s.substring(i, i + word.length))) {
      List<int> seg = [i, i + word.length - 1];
      segmentations.add(seg);
    }
  }
  return segmentations;
}

