  bool binarySearch(List<int> sortedList, int target) {
    int low = 0;
    int high = sortedList.length - 1;
    int position = -1;
    while (low <= high) {
      int mid = low + (high - low) ~/ 2;
      if (sortedList[mid] == target) {
        position = mid;
        break;
      } else if (sortedList[mid] < target) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return position != -1;
