int totalCombinations(int? k, List<String> items) {
  if (k == null || k < 0) return 0;
  if (items.isEmpty) return 1;
  int n = items.length;
  if (k > n) k = n;
  if (k <= 0) return 1;

  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(k + 1, 0));

  for (int i = 0; i <= n; i++) {
    for (int j = 0; j <= k; j++) {
      if (j == 0 || i == 0) {
        dp[i][j] = 1;
      } else {
        dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
      }
    }
  }
  return dp[n][k];
}

