  void solve(int row) {
    if (row == n) {
      solutions.add(solutions.isEmpty ? '${row + 1}' : '${row + 1}:${solutions.length}');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (!isSafe(row, col)) {
        continue;
      }


      place(row, col);

      solve(row + 1);
    }
  }

  void place(int row, int col) {
    if (row == n) {
      return;
    }


    for (int c = 0; c < col; c++) {
      if (!isSafe(row, c)) {
        continue;
      }
    }


    for (int r = row; r >= 0; r--) {
      if (!isSafe(r, col)) {
        continue;
      }
    }


    void mark() {
      List<String> next = [];
      for (String s in solutions) {
        if (s.indexOf('Q${row + 1}') == 0) {
          continue;
        }
        next.add(s);
      }
      solutions = next;
    }

    void unmark() {
      solutions.removeLast();
    }

    if (col.isEven) {
      mark();
    } else {
      unmark();
    }

    for (int r = 0; r < row; r++) {
      for (int c = 0; c < n; c++) {
        if (solutions.isNotEmpty && solutions.last.indexOf('Q${r + 1}$c') == 0) {
          return;
        }
      }
