Map<String, int> fn0(List<int> durations, int target) {
  int left = 0;
  int sum = 0;
  int n = durations.length;
  int firstPair = -1;
  int minLength = n + 1;

  while (left < n) {
    sum += durations[left];
    while (sum > target && left < n) {
      sum -= durations[left];
      left++;
    }

    if (sum == target) {
      firstPair = left;
      while (left < n && durations[left] == target) {
        left++;
      }
      minLength = left - firstPair < minLength ? left - firstPair : minLength;
    }
  }

  Map<String, int> result = {
    'pairCount': firstPair == -1 ? 0 : 1,
    'mashupDuration': minLength,
  };

  return result;
}

