Map<String, int> fn0(List<int> arrivalMinutes, int maxGap) {
  if (arrivalMinutes.isEmpty) {
    return {'pairCount': 0, 'mashupDuration': 0};
  }
  int n = arrivalMinutes.length;
  List<int> dp = List.filled(n + 1, 0);
  int maxLen = 0;
  int bestStart = -1;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      int gap = arrivalMinutes[i] - arrivalMinutes[j];
      if (gap <= maxGap) {
        dp[i] = dp[i] > dp[j] + i - j + 1 ? dp[i] : dp[j] + i - j + 1;
        if (dp[i] > maxLen) {
          maxLen = dp[i];
          bestStart = j;
        }
      }
    }
  }
  int pairCount = maxLen * 2 - 1;
  int mashupDuration = bestStart == -1 ? arrivalMinutes[0] + maxLen - 1 : arrivalMinutes[bestStart] + maxLen - 1;
  return {'pairCount': pairCount, 'mashupDuration': mashupDuration};
}

