  const Quaternion normalized() => Quaternion(x / norm(), y / norm(), z / norm(), w / norm());

  const Quaternion conjugate() => Quaternion(x, y, z, -w);

  const Quaternion inverse() {
    final double denom = norm();
    if (denom == 0) throw ArgumentError('Cannot invert zero quaternion');
    return normalized() * (1 / denom);
  }

