    final double cos = Math.cos(angle);
    final double sin = Math.sin(angle);
    final axisX = axis.x * sin + axis.z * cos;
    final axisY = axis.y * sin - axis.z * cos;
    final axisZ = -axis.x * cos + axis.y * sin;
