      Quaternion(x * other.w - other.x * w,
          y * other.w - other.y * w,
          z * other.w - other.z * w,
          w * other.x + x * other.w);

  Quaternion get conjugate =>
      Quaternion(x, y, z, -w);

  double normSquared() => x * x + y * y + z * z + w * w;

  double norm() => sqrt(normSquared());

  Quaternion get inverse => this * conjugate;

  double angle() =>
      atan2(sqrt(x * x + y * y + z * z), w);

  Quaternion normalized() => this / norm();

  Quaternion operator ^(Quaternion other) =>
      this * other * conjugate;

