    if (list.length != 4) throw ArgumentError('Invalid list length');
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  double length() {
    return x * x + y * y + z * z + w * w;
  }

  double norm() {
    return length();
  }

  double magnitude() {
    return sqrt(length());
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double invW = 1.0 / w;
    return Quaternion(x * invW, y * invW, z * invW, w * invW);
  }

