    double xQ = x * q.w - y * q.z - z * q.y;
    double yQ = y * q.w + x * q.z - z * q.x;
    double zQ = z * q.w + y * q.x - x * q.y;
    double wQ = w * q.w + x * q.y - y * q.z;
    return Quaternion(xQ, yQ, zQ, wQ);
