    return x * x - y * y - z * z + w * w;
  }

  Quaternion inverse() {
    final inv = 1.0 / norm();
    return const Quaternion(
      x * inv,
      y * inv,
      z * inv,
      w * inv,
    );
  }

  const Quaternion operator +(const other) {
    return const Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  const Quaternion operator -(const other) {
    return const Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  const Quaternion operator * (const other) {
    final x = other.w * w - y * z - x * h;
    final y = other.w * z + x * h;
    final z = other.w * h + y * w;
    final w = other.w * x + y * h;
    return const Quaternion(x, y, z, w);
  }

  const Quaternion operator * (double scalar) {
    return const Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  const Quaternion rotate(double angle, const Quaternion axis) {
    final sinA = 2.0 * angle * sin(angle);
    final cx = axis.x * sinA + (1.0 - sinA) * axis.y;
    final cy = axis.y * sinA + (1.0 - sinA) * axis.z;
    final cz = axis.z * sinA + (1.0 - sinA) * axis.w;
    final cw = sinA * 0.5;
    return const Quaternion(cx, cy, cz, cw);
  }

  const Quaternion normalized() {
    final norm = norm();
    if (norm == 0) return zero;
    return const Quaternion(x / norm, y / norm, z / norm, w / norm);
  }
