class Quaternion {
  final double x, y, z, w;
  final double norm;

  const Quaternion(this.x, this.y, this.z, this.w)
      : norm = sqrt(x * x + y * y + z * z + w * w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 0.0, 0.0, 1.0);

  const Quaternion.up() : this(0.0, 1.0, 0.0, 0.0);

  const Quaternion.down() : this(0.0, 0.0, 1.0, 0.0);

  const Quaternion.left() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.right() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle) {
    double cosHalf = cos(angle / 2);
    double sinHalf = sin(angle / 2);
    return Quaternion(
      axisX * axisX * cosHalf + axisY * axisY * cosHalf,
      axisX * axisY * sinHalf - axisY * axisX * sinHalf,
      axisZ * axisZ * cosHalf + axisX * axisX * cosHalf,
      axisZ * axisY * sinHalf + axisY * axisZ * sinHalf,
    );
  }

  const Quaternion.fromBasis(List<double> v) {
    if (v.length != 4) throw ArgumentError('Invalid basis vector');
    return Quaternion(v[0], v[1], v[2], v[3]);
  }

  Quaternion operator +(const Quaternion q) {
    return Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);
  }

  Quaternion operator -(const Quaternion q) {
    return Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);
  }

  Quaternion operator -() {
    return Quaternion(-x, -y, -z, -w);
  }

  Quaternion operator *(const Quaternion q) {
    double xx = x * q.x;
    double yy = y * q.y;
    double zz = z * q.z;
    double ww = w * q.w;
    return Quaternion(
      xx - yy - zz + ww,
      2 * (xy + q.xz),
      2 * (xz + q.yz),
      xx + yy - zz - ww,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double det = x * x + y * y + z * z + w * w;
    return (det != 0) ? conjugate() / det : Quaternion.zero();
  }

  const Quaternion normalized() {
    double norm = sqrt(x * x + y * y + z * z + w * w);
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  const Quaternion rotated(double angle, List<double> axis) {
    double cosHalf = cos(angle / 2);
    double sinHalf = sin(angle / 2);
    return Quaternion(
      x * cosHalf - y * sinHalf,
      x * sinHalf + y * cosHalf,
      z * cosHalf - w * sinHalf,
      z * sinHalf + w * cosHalf,
    );
  }

  @override
  String toString() {
    return 'q1 = $x + $y*i + $z*j + $w*k';
  }
}

