class Quaternion {
  final double q0, q1, q2, q3;
  final double norm;

  const Quaternion(this.q0, this.q1, this.q2, this.q3);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.random() : this(
        rand() * 0.5 - 0.25,
        rand() * 0.5 - 0.25,
        rand() * 0.5 - 0.25,
        rand() * 0.5 - 0.25,
      );

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle)
      : this(
          axisX * cos(angle / 2.0),
          axisY * sin(angle / 2.0),
          axisZ * sin(angle / 2.0),
          cos(angle / 2.0),
        );

  const Quaternion.fromNormalized(double x, double y, double z, double w)
      : this(x * w, y * w, z * w, w);

  const Quaternion.fromBasis(List<double> data) {
    if (data.length != 4) {
      throw ArgumentError('Invalid basis data');
    }
    return this(data[0], data[1], data[2], data[3]);
  }

  Quaternion operator +(Quaternion other) =>
      Quaternion(q0 + other.q0, q1 + other.q1, q2 + other.q2, q3 + other.q3);

  Quaternion operator -(Quaternion other) =>
      Quaternion(q0 - other.q0, q1 - other.q1, q2 - other.q2, q3 - other.q3);

  Quaternion operator *(double scalar) =>
      Quaternion(q0 * scalar, q1 * scalar, q2 * scalar, q3 * scalar);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
        q0 * other.q0 - q1 * other.q1 - q2 * other.q2 - q3 * other.q3,
        q0 * other.q1 + q1 * other.q0 + q2 * other.q3 - q3 * other.q2,
        q0 * other.q2 + q1 * other.q3 + q2 * other.q0 - q3 * other.q1,
        q0 * other.q3 + q1 * other.q2 + q2 * other.q1 - q3 * other.q0,
      );

  Quaternion conjugate() =>
      Quaternion(q0, q1, q2, -q3);

  Quaternion inverse() =>
      Quaternion(
        q0 * q0 + q1 * q1 + q2 * q2 + q3 * q3,
        -q0 * q1 + q1 * q0,
        -q0 * q2 + q2 * q0,
        -q0 * q3 + q3 * q0,
      );

  double norm => sqrt(q0 * q0 + q1 * q1 + q2 * q2 + q3 * q3);

  Quaternion normalized() =>
      Quaternion(q0 / norm, q1 / norm, q2 / norm, q3 / norm);

  static const Quaternion pi = const Quaternion.fromAxisAngle(0.0, 0.0, 1.0, pi);

  static const Quaternion identity = const Quaternion.zero();

  @override
  bool operator ==(covariant Quaternion other) =>
      q0 == other.q0 && q1 == other.q1 && q2 == other.q2 && q3 == other.q3;

  @override
  int get hashCode => q0.hashCode ^ q1.hashCode ^ q2.hashCode ^ q3.hashCode;

  @override
  String toString() {
    const zero = Quaternion.zero();
    if (q0 == 0.0 && q1 == 0.0 && q2 == 0.0 && q3 == 0.0) return '0';
    if (q0 == 0.0 && q1 == 0.0 && q2 == 0.0) {
      return '$q3';
    }
    if (q0 == 0.0) {
      return '$q1 + $q2*i + $q3*j';
    }
    if (q1 == 0.0) {
      return '$q0 + $q3*i + $q2*j';
    }
    if (q2 == 0.0) {
      return '$q0 + $q1*i + $q3*j';
    }
    if (q3 == 0.0) {
      return '$q0 + $q1*i + $q2*j';
    }
    final realPart = q0 > 0.0 ? q0 : -q0;
    final imaginaryPart = q1 > 0.0 ? q1 : -q1;
    final jPart = q2 > 0.0 ? q2 : -q2;
    final kPart = q3 > 0.0 ? q3 : -q3;
    return realPart == 0.0
        ? '$imaginaryPart*i + $jPart*j'
        : '$realPart + $imaginaryPart*i + $jPart*j';
  }
}

