int totalCombinations(int n, int k, int start, int taken) {

  if (k <= 0 || start > n) return 0;

  if (k == 1) return totalCombinations(n - 1, 1, start + 1, taken + 1);

  int total = 0;

  for (int i = start; i <= n - k + 1; i++) {
    int j = i;
    while (j < start) {
      j++;
    }
    if (j == start) {
      total += totalCombinations(n - i, k - 1, start + 1, taken + 1);
    }
  }

  return total;
}

