            dp[i] = dp[i] > dp[j] + 1 ? dp[i] : dp[j] + 1;
          }
        }
      }
    }
  }

  Map<String, int> result = {};
  String faceOrSuit = "";
  int maxLen = -1;

  for (int i = n; i >= 1; i--) {
    if (dp[i] > maxLen) {
      maxLen = dp[i];
      faceOrSuit = cards[i - 1] >= 11 ? "face" : "suit";
    } else if (dp[i] == maxLen && cards[i - 1] >= 11) {
      faceOrSuit = "face";
    } else {
      break;
    }

    if (maxLen > 0) {
