Map<String, int> fn0(List<int> rounds, int target) {
  if (rounds.isEmpty || rounds.length < 2) return {"x": -1, "y": -1};
  List<List<int>> dp = List.generate(rounds.length, (_) => List.filled(rounds.length, 0));
  for (int i = 0; i < rounds.length; i++) dp[i][i] = rounds[i];
  for (int len = 2; len <= rounds.length; len++) {
    for (int i = 0; i <= rounds.length - len; i++) {
      int j = i + len - 1;
      int sum = rounds[i] + rounds[j];
      if (sum == target) {
        dp[i][j] = rounds[i];
        break;
      }
      if (sum > target) dp[i][j] = dp[i + 1][j];
      else if (sum < target) dp[i][j] = dp[i][j - 1];
      else if (len > 2) dp[i][j] = dp[i + 1][j - 1];
    }
  }
  int x = -1, y = -1;
  for (int i = 0; i <= rounds.length; i++) {
    for (int j = 0; j <= rounds.length; j++) {
      if (dp[i][j] == target) { x = i; y = j; break; }
    }
    if (x != -1 && y != -1) break;
  }
  return {"x": x, "y": y};
}

