List<int> matchesIndices(String text, String pattern) {
  List<int> indices = [];
  int textLen = text.length;
  int patLen = pattern.length;
  if (patLen == 0) {
    return indices;
  }

  for (int i = 0; i <= textLen - patLen; i++) {
    bool match = true;
    for (int j = 0; j < patLen; j++) {
      if (text[i + j] != pattern[j]) {
        match = false;
        break;
      }
    }
    if (match) {
      indices.add(i);
    }
  }
  return indices;
}

