int computeLPSArray(String pattern) {
  int n = pattern.length;
  List<int> lps = List.filled(n, 0);
  int len = 0;
  int i = 1;

  while (i < n) {
    if (pattern[i] == pattern[len]) {
      len++;
      lps[i] = len;
      i++;
    } else {
      if (len != 0) {
        len = lps[len - 1];
      } else {
        lps[i] = 0;
        i++;
      }
    }
  }

  return lps;
}

List<int> findPatternIndices(String text, String pattern) {
  int textLen = text.length;
  int patternLen = pattern.length;

  List<int> result = [];
  int j = 0; 

  for (int i = 0; i < textLen; i++) {
    if (pattern[j] == text[i]) {
      j++;
    }

    if (j == patternLen) {
      result.add(i - j);
      j = lps[j - 1];
    } else if (i - j >= 0 && pattern[j] != text[i]) {
      if (j != 0) {
        j = lps[j - 1];
      } else {
        i++;
      }
    }
  }

  return result;
}

