@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  final n = int.tryParse(args[0]) ?? 0;

  if (n < 0) {
    print('Please provide a non-negative integer (e.g., "dart run main.dart 20").');
    return;
  }

  Map<int, BigInt> memo = {};

  BigInt fib(int k) {
    if (k <= 1) {
      return k;
    }
    if (memo.containsKey(k)) {
      return memo[k]!;
    }
    memo[k] = fib(k - 1) + fib(k - 2);
    return memo[k]!;
  }

  print('F($n) = ${fib(n)}');
}

