Set<int> fn0(String schedule) {
  Set<int> blocked = {};
  if (schedule.isEmpty) {
    return blocked;
  }

  List<String> slots = schedule.split('|');
  for (String slot in slots) {
    if (slot.length < 2) {
      continue;
    }

    String timeStr = slot[0];
    int hour = timeStr.codeUnitAt(0) - 48;
    int minute = timeStr.codeUnitAt(1) - 48;

    String action = slot[2];
    if (action != '.' && action != '-') {
      continue;
    }

    for (int i = 3; i < slot.length; i++) {
      if (slot[i] != ' ') {
        continue;
      }

      String durationStr = slot.substring(i + 1);
      if (durationStr.isEmpty) {
        continue;
      }

      int minutes = 0;
      for (int j = 0; j < durationStr.length; j++) {
        minutes = minutes * 10 + (durationStr.codeUnitAt(j) - 48);
      }

      int start = hour * 60 + minute;
      int end = start + minutes;
      if (action == '.') {
        blocked.add(start);
      } else {
        blocked.add(end);
      }
    }
  }

  return blocked;
}

