int fn0(List<List<int>> pixels, int interval) {
  int score = 0;
  for (int i = 0; i < pixels.length; i++) {
    List<int> pixel = pixels[i];
    int r = pixel[0];
    int g = pixel[1];
    int b = pixel[2];
    int dominant = r;
    if (g > dominant) dominant = g;
    if (b > dominant) dominant = b;
    int dominantVal = dominant;
    bool isDominant = false;
    if (dominantVal >= interval) {
      isDominant = true;
      score += 3;
    }
    bool adjacent = false;
    for (int j = 0; j < i; j++) {
      List<int> prevPixel = pixels[j];
      int prevR = prevPixel[0];
      int prevG = prevPixel[1];
      int prevB = prevPixel[2];
      int prevDominant = prevR;
      if (prevG > prevDominant) prevDominant = prevG;
      if (prevB > prevDominant) prevDominant = prevB;
      int diff = (r - prevR).abs() + (g - prevG).abs() + (b - prevB).abs();
      if (diff <= interval) {
        adjacent = true;
        score += diff;
        break;
      }
    }
    if (!isDominant) score += 1;
    if (adjacent) score += 2;
  }
  return score;
}

