  Uint8List bytesBE = Uint8List.filled(4, 0);
  bytesBE.setAll(0, value.toRadixString(16).padLeft(4, '0').codeUnits);
  bytesBE.reverse();

  print('Little-endian bytes: ${toHex(fromLittleEndianBytes(bytesLE))}');
  print('Big-endian bytes: ${toHex(fromBigEndianBytes(bytesBE))}');

  Uint8List swappedLE = Uint8List.filled(4, 0);
  swappedLE.setAll(0, value.toRadixString(16).padLeft(4, '0').codeUnits);
