    'read': ['view', 'edit'],
    'write': ['create', 'edit'],
    'delete': ['delete'],
    'admin': ['manage', 'remove'],
  };

  final Map<String, List<String>> resourceAccess = {
    'document1': ['read', 'write'],
    'document2': ['read'],
    'sensitive_data': ['admin'],
  };

  final Map<String, int> accessMatrix = {
    'read': 0,
    'write': 1,
    'delete': 2,
    'admin': 3,
  };

  String getRoleName(int roleFlags) {
    if ((roleFlags & 1) != 0) return 'admin';
    if ((roleFlags & 2) != 0) return 'editor';
    if ((roleFlags & 4) != 0) return 'moderator';
    if ((roleFlags & 8) != 0) return 'viewer';
    return 'unknown';
  }

  bool hasPermission(String role, String permission) {
    return permissions[permission]!.contains(getRoleName(roles[role]!));
  }

  bool canAccessResource(String role, String resource, String permission) {
    if (resourceAccess.containsKey(resource)) {
      final Map<String, int> resourcePermissions = resourceAccess[resource]!;
      return hasPermission(role, permission) &&
          resourcePermissions[permission] == accessMatrix[permission];
    }
    return false;
  }

  void grantAccess(String user, String role, String resource, String permission) {
    if (user.isEmpty) return;
    final String userRole = '${user}_$role';
    roles[userRole] = roles[role]!;
    permissions[permission]!.add(userRole);
  }

  void denyAccess(String user, String resource, String permission) {
    if (user.isEmpty) return;
    final String userRole = '${user}_$role';
    roles.remove(userRole);
    permissions[permission]!.remove(userRole);
  }

  bool checkAccess(String user, String resource, String permission) {
    String role = '${user}_$role';
    if (!roles.containsKey(role)) return false;
    return canAccessResource(role, resource, permission);
  }

  Map<String, int> permissionsOf(String role) {
    if (!roles.containsKey(role)) return {};
    final Map<String, int> permissions = {};
    for (var p in permissions[role]!) {
      permissions[p] = (permissions[p] ?? 0) + 1;
    }
    return permissions;
  }

  print('=== Role-Based Access Control System ===\n');

  grantAccess('alice', 'editor', 'document1', 'write');
  grantAccess('bob', 'viewer', 'document1', 'read');

  print('User: alice');
