  bool _checkAccess(Map<String, List<String>> roles, String role, String resource) {
    bool granted = false;
    if (roles.containsKey(role)) {

      final Map<String, List<String>> permissionsOfRole = roles[role]!;
      if (permissionsOfRole.containsKey(resource)) {
        final List<String> permissionsForResource = permissionsOfRole[resource]!;
        if (permissionsForResource.isNotEmpty) {
          granted = true;
        }
