String roleHierarchyToString(Map<String, List<String>> roles) {
  if (roles.isEmpty) return '';
  final Map<String, List<String>> reversed = {};
  for (final role in roles.keys) {
    reversed[role] = roles[role]!.reversed.toList();
  }
  StringBuffer sb = StringBuffer();
  bool first = true;
  for (final role in roles.keys) {
    if (first) {
      sb.write(role); first = false;
    } else {
      sb.write(' → $role');
    }
  }
  return sb.toString();
}

