Set<int> findFrequentItemsets(List<String> items, int minSupportItems, int minSupport, Map<String, Set<int>> parent) {
  if (items.isEmpty) {
    return {};
  }

  if (items.length == 1) {
    String item = items[0];
    return parent.containsKey(item) ? parent[item]! : {0};
  }

  int k = items.length;
  int k1 = k ~/ 2;

  Map<String, Set<int>> left = {};
  Map<String, Set<int>> right = {};

  for (int i = 0; i < items.length; i++) {
    if (i < k1) {
      left[items[i]] = {};
    } else {
      right[items[i]] = {};
    }
  }

  for (int i = 0; i < items.length; i++) {
    for (int j = 0; j < i; j++) {
      int leftSupport = left[items[i]]!.length;
      int rightSupport = right[items[j]]!.length;

      if (leftSupport >= minSupport && rightSupport >= minSupport) {
        int unionSupport = leftSupport + rightSupport;
        String itemset = [items[i], items[j]].toList()..sort().join(',');
        parent[itemset] = unionSupport == 1 ? {0} : null;
      }
    }
  }

  return parent[items.join(',')] ?? {};
}

