  int total = 0;
  int highestPriorityRow = 0;
  int lowestPriorityRow = 0;

  for (var i = 0; i < grid.length; i++) {
    final row = grid[i];
    final dryCount = row.fold(0, (a, b) => a + b);
    final rowIndex = row.length;
    final cells = List.generate(row.length, (j) => row[j]);
    final mapEntry = MapEntry(i, row.length);
