      }
    }

    if (lastMoistRow != null) {
      final rowLength = row.length;
      final rowSpan = row[0] == 1 ? rowLength : row[rowLength - 1];
      final start = lastMoistCellIndex;
      final end = start + rowSpan - 1;
      final range = row[0] == 1 ? start : end;

