    final da = a.value - a.key;
    final db = b.value - b.key;
    if (da != db) return da.compareTo(db);
    return a.key.compareTo(b.key);
  });

  final first = rows.first;
  final last = rows.last;
  final mid = rows.length ~/ 2;

  return {
    'index': first.key,
    'range': first.value,
    'total': total,
    'dryCells': dryCells,
    'lowestPriorityRow': last.key,
    'highestPriorityRow': mid,
    'rowsNeedingReview': rowsNeedingReview.length,
