class Rectangle {
  final double width;
  final double height;
  final double centerX;
  final double centerY;

  Rectangle(this.width, this.height, [this.centerX = 0.0, this.centerY = 0.0]);

  Rectangle.unit() : this(1.0, 1.0);

  Rectangle.square(double side) : this(side, side);

  Rectangle.centered(double x, double y)
      : this(x - 0.5 * width, y - 0.5 * height, x, y);

  bool contains(Point p) =>
      p.x >= centerX - width / 2 &&
      p.x <= centerX + width / 2 &&
      p.y >= centerY - height / 2 &&
      p.y <= centerY + height / 2;

  bool overlaps(Rectangle other) =>
      !contains(other.p1) && !contains(other.p2) &&
      other.contains(p1) && other.contains(p2);

  Point get p1 => Point(centerX - width / 2, centerY - height / 2);
  Point get p2 => Point(centerX + width / 2, centerY + height / 2);

  Rectangle union(Rectangle other) {
    final newW = other.width + width;
    final newH = other.height + height;
    final newX = (centerX - width / 2 < other.centerX - other.width / 2)
        ? other.centerX - other.width / 2
        : centerX - width / 2;
    final newY = (centerY - height / 2 < other.centerY - other.height / 2)
        ? other.centerY - other.height / 2
        : centerY - height / 2;
    return Rectangle(newW, newH, newX, newY);
  }

  @override
  String toString() =>
      'Rectangle(center: ($centerX, $centerY), halfWidth: $width, halfHeight: $height)';
}

