  const Rectangle.unit() : this(1, 1, 0, 0);
  const Rectangle.unitX() : this(1, 1, 0);
  const Rectangle.unitY() : this(1, 1, 0, 1);
  const Rectangle.originX() : this(1, 1, 0);

