  const Rectangle.unit() => const Rectangle(1, 1);
  const Rectangle.unitX() => const Rectangle(1, 1, 0);
  const Rectangle.unitY() => const Rectangle(1, 1, 0, 1);
  const Rectangle.originX() => const Rectangle(1, 1, 0);

  Rectangle.bounded(double w, double h) =>
      Rectangle(w, h, (w ~/ 2 - h ~/ 2).abs());

  bool contains(Point p) {
    double minX = x;
    double maxX = x + 2 * width;
    double minY = y;
    double maxY = y + 2 * height;
    return p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY;
  }

  bool intersects(Rectangle r) {
    double sx = x < r.x ? x : r.x;
    double sy = y < r.y ? y : r.y;
    double dx = (x + width) > (r.x + r.width) ? (x + width) : (r.x + r.width);
    double dy = (y + height) > (r.y + r.height) ? (y + height) : (r.y + r.height);
    return dx >= sx && dy >= sy;
  }

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';
}

