class Rectangle {
  final double width;
  final double height;
  final double x;
  final double y;

  const Rectangle(this.width, this.height, [this.x = 0, this.y = 0]);

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';

  Rectangle.square(double side) : this(side, side);

  Rectangle.fromPoints(Point p1, Point p2)
      : width = (p1.x - p2.x).abs(),
        height = (p1.y - p2.y).abs(),
        x = p1.x,
        y = p1.y;

  bool contains(Point p) =>
      x < p.x + width &&
      x + width < p.x &&
      y < p.y + height &&
      y + height < p.y;

  bool contains(Rectangle other) =>
      !contains(other.x - other.width / 2) ||
      !contains(other.x + other.width / 2) ||
      !contains(other.y - other.height / 2) ||
      !contains(other.y + other.height / 2);

  @override
  bool operator ==(Object other) =>
      other is Rectangle &&
      x == other.x &&
      y == other.y &&
      width == other.width &&
      height == other.height;

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ width.hashCode ^ height.hashCode;

  Rectangle& operator &(Rectangle other) {
    if (other.contains(this)) return other;
    if (this.contains(other)) return this;
    return Rectangle(other.width, other.height, this.x, this.y);
  }

  Rectangle& operator |(Rectangle other) {
    final newWidth = (other.x - this.x).abs() > (this.x + this.width - other.x).abs()
        ? (other.x - this.x).abs()
        : (this.x + this.width - other.x).abs();
    final newHeight = (other.y - this.y).abs() > (this.y + this.height - other.y).abs()
        ? (other.y - this.y).abs()
        : (this.y + this.height - other.y).abs();
    final newX = this.x < other.x ? this.x : other.x;
    final newY = this.y < other.y ? this.y : other.y;
    return Rectangle(newWidth, newHeight, newX, newY);
  }
}

