class Rectangle {
  final Point center;
  final double halfWidth;
  final double halfHeight;

  const Rectangle(this.center, this.halfWidth)
      : halfHeight = halfWidth * sqrt(2),
        super();

  const Rectangle.origin(double halfWidth)
      : this(Point.origin(), halfWidth),
        super();

  const Rectangle.unit(double halfWidth)
      : this(Point.unit(), halfWidth),
        super();

  const Rectangle.unitX(double halfWidth)
      : this(Point.unitX(), halfWidth),
        super();

  const Rectangle.unitY(double halfWidth)
      : this(Point.unitY(), halfWidth),
        super();

  const Rectangle.unitNegative(double halfWidth)
      : this(Point.unitNegative(), halfWidth),
        super();

  const Rectangle.unitNegativeX(double halfWidth)
      : this(Point.unitNegativeX(), halfWidth),
        super();

  const Rectangle.unitNegativeY(double halfWidth)
      : this(Point.unitNegativeY(), halfWidth),
        super();

  @override
  String toString() => 'Rectangle(center: ${center.x},${center.y}, halfWidth: $halfWidth, halfHeight: $halfHeight)';

  bool contains(Point p) {
    return (p.x - center.x).abs() <= halfWidth &&
        (p.y - center.y).abs() <= halfHeight;
  }
}

