      : this(minX - maxX, minY - maxY);

  const Point.square3(double minX, double maxX, double minY, double maxY)
      : this(minX + maxX, minY - maxY);

  const Point.square4(double minX, double maxX, double minY, double maxY)
      : this(minX - maxX, minY + maxY);

