  const Point.unitCircle2() : this(sqrt(2), sqrt(2));

  const Point.unitCircle3() : this(-sqrt(2), -sqrt(2));

  const Point.unitCircle4() : this(-sqrt(2) - 1, -sqrt(2) - 1);

  const Point.unitHalfCircle() : this(sqrt(2) / 2, sqrt(2) / 2);
}

