void fn0() {

  final rand = Random(0);
  final points = <List<double>>[
    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 4.0],
    [4.0, 4.5],
    [4.5, 7.0],
    [2.0, 3.0],
  ];

  final int k = 2; 
  final int maxIterations = 50;

  double eps = double.infinity; 
  int minPts = 3; 
  List<int> clusterLabels = List.filled(points.length, -1);

  for (int i = 0; i < points.length; i++) {
    clusterLabels[i] = -1;
  }

  List<int> regionQuery(int index) {
    List<int> neighbors = [];
    for (int j = 0; j < points.length; j++) {
      if ((points[index][0] - points[j][0]).abs() +
          (points[index][1] - points[j][1]).abs() <= eps) {
        neighbors.add(j);
      }
    }
    return neighbors;
  }

  for (int i = 0; i < points.length; i++) {
    if (clusterLabels[i] != -1) continue;

    int clusterId = i;
    List<int> region = regionQuery(i);

    if (region.length < minPts) {
      clusterLabels[i] = 0;
    } else {
      List<int> seeds = List<int>.from(region);
      List<int> expanded = List<int>.from(region);

      while (seeds.isNotEmpty) {
        int current = seeds.removeLast();

        if (clusterLabels[current] == -1) {
          clusterLabels[current] = clusterId;
        }

        expanded.add(current);

        for (int neighbor in regionQuery(current)) {
          if (!expanded.contains(neighbor)) {
            seeds.add(neighbor);
          }
        }
      }

      clusterLabels[i] = clusterId;
    }
  }

  int iterations = 0;
  bool converged = false;

  while (!converged && iterations < maxIterations) {
    List<int> newLabels = List<int>.filled(points.length, -1);

    for (int i = 0; i < points.length; i++) {
      if (clusterLabels[i] == -1) continue;

      int clusterId = clusterLabels[i];
      List<int> region = regionQuery(i);

      if (region.length >= minPts) {
        newLabels[i] = clusterId;

        for (int j = 0; j < points.length; j++) {
          if (clusterLabels[j] == clusterId) {
            newLabels[j] = clusterId;
          }
        }
      }
    }

    for (int i = 0; i < points.length; i++) {
      if (newLabels[i] != clusterLabels[i]) {
        converged = false;
        break;
      }
    }

    for (int i = 0; i < points.length; i++) {
      clusterLabels[i] = newLabels[i];
    }

    iterations++;
  }

  print('Cluster ${clusterLabels.length} centroids:');
  for (int i = 0; i < clusterLabels.length; i++) {
    if (clusterLabels[i] != -1) {
      print('Cluster $i:');
      for (int j = 0; j < points.length; j++) {
        if (clusterLabels[j] == i) {
          print('  Points: $points[j]');
        }
      }
    }
  }

  print('Converged in $iterations iteration(s).');
}

